        "conceptosClave": [
          {
            "termino": "Consentimiento informado",
            "definicion": "Aceptación expresa de la atención por un paciente capaz, tras explicársele en lenguaje comprensible qué se hará, para qué y con qué riesgos."
          },
          {
            "termino": "Actuación en urgencia sin autorización previa",
            "definicion": "Conducta prevista por la Ley General de Salud cuando la persona está incapacitada y no hay familiar acompañante ni representante legal: se procede a preservar la vida y la salud, dejando constancia."
          },
          {
            "termino": "Dato personal sensible",
            "definicion": "Aquel cuya utilización indebida puede originar discriminación o un riesgo grave; el estado de salud lo es conforme a la Ley Federal de Protección de Datos Personales en Posesión de los Particulares."
          },
          {
            "termino": "Cadena de custodia",
            "definicion": "Sistema de control y registro que se aplica al indicio desde su localización hasta que la autoridad competente ordena su conclusión, según el artículo 227 del Código Nacional de Procedimientos Penales."
          },
          {
            "termino": "Capacidad de decisión",
            "definicion": "Aptitud para comprender la situación, las alternativas y las consecuencias de rechazar la atención; no se pierde por estar en desacuerdo."
          },
          {
            "termino": "Abandono",
            "definicion": "Retirarse de un paciente que requiere atención sin transferirlo a alguien de igual o mayor capacidad."
          },
          {
            "termino": "Nota aclaratoria",
            "definicion": "Corrección fechada y firmada que se añade a un registro cerrado; sustituye a la alteración del documento original."
          }
        ],
