        "conceptosClave": [
          {
            "termino": "Oclusión intestinal",
            "definicion": "Detención del tránsito del contenido a lo largo del intestino, con acumulación y distensión por encima del punto donde se detiene."
          },
          {
            "termino": "Oclusión mecánica",
            "definicion": "La producida por un obstáculo físico: adherencias de cirugías previas, hernias, tumores o cuerpos extraños."
          },
          {
            "termino": "Oclusión funcional",
            "definicion": "La que ocurre sin obstáculo porque el intestino deja de moverse, por ejemplo tras una cirugía o en trastornos electrolíticos."
          },
          {
            "termino": "Tétrada clásica",
            "definicion": "Dolor cólico, vómitos, distensión abdominal y ausencia de emisión de gases y heces."
          },
          {
            "termino": "Silencio abdominal",
            "definicion": "Desaparición de los ruidos intestinales tras una fase de ruidos de lucha; indica que el cuadro ha avanzado y no que haya mejorado."
          }
        ],
