        "conceptosClave": [
          {
            "termino": "Obstrucción leve",
            "definicion": "Aquella en que el paciente tose con eficacia y puede emitir sonido; no se interviene con maniobras."
          },
          {
            "termino": "Obstrucción grave",
            "definicion": "Aquella en que la tos es débil o ausente y el paciente no puede emitir sonido ni ventilar adecuadamente."
          },
          {
            "termino": "Golpes dorsales",
            "definicion": "Impactos con el talón de la mano entre los omóplatos, primera serie de maniobras tanto en el lactante como en el niño."
          },
          {
            "termino": "Compresiones torácicas en el lactante",
            "definicion": "Maniobra que sustituye a las compresiones abdominales en el lactante con obstrucción grave."
          },
          {
            "termino": "Barrido a ciegas",
            "definicion": "Búsqueda del cuerpo extraño con el dedo sin verlo; está proscrita porque puede empujarlo más adentro."
          }
        ],
        "flashcards": [
          {
            "frente": "¿Qué se hace ante una obstrucción leve?",
            "reverso": "No intervenir: animar a toser y vigilar de cerca, porque la tos es más eficaz que cualquier maniobra."
          },
          {
            "frente": "¿Qué maniobras se combinan en el lactante?",
            "reverso": "Golpes dorsales y compresiones torácicas."
          },
          {
            "frente": "¿Por qué no se aplican compresiones abdominales al lactante?",
            "reverso": "Porque su hígado y su bazo están menos cubiertos por la parrilla costal y pueden lesionarse."
          },
          {
            "frente": "¿Qué maniobras se combinan en el niño?",
            "reverso": "Golpes dorsales y compresiones abdominales."
          },
          {
            "frente": "¿Se busca el objeto con el dedo?",
            "reverso": "Nunca a ciegas: solo se retira lo que se ve con claridad y puede extraerse con seguridad."
          },
          {
            "frente": "¿Qué se hace si el paciente deja de responder?",
            "reverso": "Activar el sistema, iniciar la secuencia de reanimación y mirar la boca cada vez que se abra la vía aérea."
          }
        ],
